-- RRC150: one explicit missing pommel and trivial repair; fresh dedicated strict MariaDB session.
DELIMITER //
BEGIN NOT ATOMIC
 DECLARE own_transaction BOOLEAN DEFAULT FALSE;
 DECLARE recipes_before BIGINT DEFAULT 0;
 DECLARE entries_before BIGINT DEFAULT 0;
 DECLARE locked_rows BIGINT DEFAULT 0;
 DECLARE changed_rows BIGINT DEFAULT 0;
 DECLARE changed_recipe_rows BIGINT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
  IF own_transaction THEN ROLLBACK;END IF;
  RESIGNAL;
 END;
 IF @@in_transaction<>0 OR DATABASE()<>'peq_housing_test' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 invalid target/transaction';END IF;
 IF FIND_IN_SET('STRICT_ALL_TABLES',@@SESSION.sql_mode)=0 AND FIND_IN_SET('STRICT_TRANS_TABLES',@@SESSION.sql_mode)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 strict mode required';END IF;
 IF(SELECT COUNT(*)FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME IN('tradeskill_recipe','tradeskill_recipe_entries','items')AND ENGINE='InnoDB')<>3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 InnoDB mismatch';END IF;
 CREATE TEMPORARY TABLE rrc150_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc150_after_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc150_before LIKE tradeskill_recipe_entries;
 INSERT INTO rrc150_recipes(`id`,`name`,`tradeskill`,`skillneeded`,`trivial`,`nofail`,`replace_container`,`notes`,`must_learn`,`learned_by_item_id`,`quest`,`enabled`,`min_expansion`,`max_expansion`,`content_flags`,`content_flags_disabled`)VALUES
(4507,CONVERT(0x466f726765642056656c69756d2053686f72742053776f7264 USING utf8mb4),63,0,70,0,0,NULL,0,0,0,1,-1,-1,NULL,NULL);
 INSERT INTO rrc150_after_recipes(`id`,`name`,`tradeskill`,`skillneeded`,`trivial`,`nofail`,`replace_container`,`notes`,`must_learn`,`learned_by_item_id`,`quest`,`enabled`,`min_expansion`,`max_expansion`,`content_flags`,`content_flags_disabled`)VALUES
(4507,CONVERT(0x466f726765642056656c69756d2053686f72742053776f7264 USING utf8mb4),63,0,108,0,0,NULL,0,0,0,1,-1,-1,NULL,NULL);
 INSERT INTO rrc150_before(`id`,`recipe_id`,`item_id`,`successcount`,`failcount`,`componentcount`,`salvagecount`,`iscontainer`)VALUES
(44031,4507,12046,0,0,1,1,0),
(44032,4507,22076,0,0,1,1,0),
(44033,4507,22095,0,0,1,1,0),
(44034,4507,22564,0,0,1,1,0),
(44035,4507,30278,1,0,0,0,0),
(44036,4507,17,0,0,0,0,1);
 START TRANSACTION;
 SET own_transaction=TRUE;
 SELECT COUNT(*)INTO recipes_before FROM tradeskill_recipe;
 SELECT COUNT(*)INTO entries_before FROM tradeskill_recipe_entries;
 SELECT COUNT(*)INTO locked_rows FROM tradeskill_recipe WHERE id=4507 FOR UPDATE;
 IF locked_rows<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 recipe missing';END IF;
 SELECT COUNT(*)INTO locked_rows FROM tradeskill_recipe_entries WHERE recipe_id=4507 FOR UPDATE;
 IF locked_rows<>6 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 target entry multiplicity';END IF;
 IF EXISTS(SELECT 1 FROM rrc150_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND BINARY r.`name` <=> BINARY e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND BINARY r.`notes` <=> BINARY e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND BINARY r.`content_flags` <=> BINARY e.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 recipe drift';END IF;
 IF EXISTS(SELECT 1 FROM rrc150_before e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR(SELECT COUNT(*)FROM tradeskill_recipe_entries WHERE recipe_id=4507)<>6 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 old entry/count drift';END IF;
 IF(SELECT COUNT(*)FROM tradeskill_recipe_entries WHERE `recipe_id` <=> 4507 AND `item_id` <=> 12060 AND `successcount` <=> 0 AND `failcount` <=> 0 AND `componentcount` <=> 1 AND `salvagecount` <=> 1 AND `iscontainer` <=> 0)<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 named component state mismatch';END IF;
 IF(SELECT COUNT(*)FROM items WHERE `id` <=> 12046 AND BINARY Name=BINARY CONVERT(0x48696c74204d6f6c64 USING utf8mb4) AND `size` <=> 0 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 0 AND `stacksize` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535 AND `races` <=> 65535 AND `deity` <=> 0 AND `damage` <=> 0 AND `delay` <=> 0 AND `range` <=> 0 AND `slots` <=> 0 AND `purity` <=> 0 AND `augtype` <=> 0 AND `reqlevel` <=> 0 AND `reclevel` <=> 0 AND `loregroup` <=> 0 AND `filename` <=> '' AND `booktype` <=> 0)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 native semantics drift';END IF;
 IF(SELECT COUNT(*)FROM items WHERE `id` <=> 12060 AND BINARY Name=BINARY CONVERT(0x506f6d6d656c204d6f6c64 USING utf8mb4) AND `size` <=> 0 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 0 AND `stacksize` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535 AND `races` <=> 65535 AND `deity` <=> 0 AND `damage` <=> 0 AND `delay` <=> 0 AND `range` <=> 0 AND `slots` <=> 0 AND `purity` <=> 0 AND `augtype` <=> 0 AND `reqlevel` <=> 0 AND `reclevel` <=> 0 AND `loregroup` <=> 0 AND `filename` <=> '' AND `booktype` <=> 0)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 native semantics drift';END IF;
 IF(SELECT COUNT(*)FROM items WHERE `id` <=> 22076 AND BINARY Name=BINARY CONVERT(0x53686f727420426c616465204d6f6c64 USING utf8mb4) AND `size` <=> 0 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 0 AND `stacksize` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535 AND `races` <=> 65535 AND `deity` <=> 0 AND `damage` <=> 0 AND `delay` <=> 0 AND `range` <=> 0 AND `slots` <=> 0 AND `purity` <=> 0 AND `augtype` <=> 0 AND `reqlevel` <=> 0 AND `reclevel` <=> 0 AND `loregroup` <=> 0 AND `filename` <=> '' AND `booktype` <=> 0)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 native semantics drift';END IF;
 IF(SELECT COUNT(*)FROM items WHERE `id` <=> 22095 AND BINARY Name=BINARY CONVERT(0x5368656574206f662056656c69756d USING utf8mb4) AND `size` <=> 1 AND `itemclass` <=> 0 AND `itemtype` <=> 17 AND `stackable` <=> 1 AND `stacksize` <=> 20 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535 AND `races` <=> 65535 AND `deity` <=> 0 AND `damage` <=> 0 AND `delay` <=> 0 AND `range` <=> 0 AND `slots` <=> 0 AND `purity` <=> 0 AND `augtype` <=> 0 AND `reqlevel` <=> 0 AND `reclevel` <=> 0 AND `loregroup` <=> 0 AND `filename` <=> '' AND `booktype` <=> 0)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 native semantics drift';END IF;
 IF(SELECT COUNT(*)FROM items WHERE `id` <=> 22564 AND BINARY Name=BINARY CONVERT(0x436f6c6461696e2056656c69756d2054656d706572 USING utf8mb4) AND `size` <=> 0 AND `itemclass` <=> 0 AND `itemtype` <=> 17 AND `stackable` <=> 1 AND `stacksize` <=> 20 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535 AND `races` <=> 65535 AND `deity` <=> 0 AND `damage` <=> 0 AND `delay` <=> 0 AND `range` <=> 0 AND `slots` <=> 0 AND `purity` <=> 0 AND `augtype` <=> 0 AND `reqlevel` <=> 0 AND `reclevel` <=> 0 AND `loregroup` <=> 0 AND `filename` <=> '' AND `booktype` <=> 0)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 native semantics drift';END IF;
 IF(SELECT COUNT(*)FROM items WHERE `id` <=> 30278 AND BINARY Name=BINARY CONVERT(0x466f726765642056656c69756d2053686f72742053776f7264 USING utf8mb4) AND `size` <=> 2 AND `itemclass` <=> 0 AND `itemtype` <=> 0 AND `stackable` <=> 0 AND `stacksize` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 413 AND `races` <=> 65535 AND `deity` <=> 0 AND `damage` <=> 5 AND `delay` <=> 23 AND `range` <=> 0 AND `slots` <=> 24576 AND `purity` <=> 0 AND `augtype` <=> 0 AND `reqlevel` <=> 0 AND `reclevel` <=> 0 AND `loregroup` <=> 0 AND `filename` <=> '' AND `booktype` <=> 0)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 native semantics drift';END IF;
 IF(SELECT COUNT(DISTINCT a.recipe_id)FROM tradeskill_recipe_entries a WHERE a.item_id=22564 AND a.componentcount>0 AND a.iscontainer=0 AND(SELECT SUM(e.componentcount)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0)=4 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=12046)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=22076)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=22095)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=22564)=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 full input universe drift';END IF;
 IF(SELECT COUNT(DISTINCT a.recipe_id)FROM tradeskill_recipe_entries a WHERE a.item_id=22564 AND a.componentcount>0 AND a.iscontainer=0 AND(SELECT SUM(e.componentcount)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0)=5 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=22564)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=12046)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=12060)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=22095)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=22076)=1)<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 full input universe drift';END IF;
 INSERT INTO tradeskill_recipe_entries(`recipe_id`,`item_id`,`successcount`,`failcount`,`componentcount`,`salvagecount`,`iscontainer`)VALUES
(4507,12060,0,0,1,1,0);
 SET changed_rows=ROW_COUNT();
 IF changed_rows<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 changed entry mismatch';END IF;
 UPDATE tradeskill_recipe r JOIN rrc150_after_recipes e ON e.id=r.id SET r.trivial=e.trivial;
 SET changed_recipe_rows=ROW_COUNT();
 IF changed_recipe_rows<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 changed definition mismatch';END IF;
 IF EXISTS(SELECT 1 FROM rrc150_after_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND BINARY r.`name` <=> BINARY e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND BINARY r.`notes` <=> BINARY e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND BINARY r.`content_flags` <=> BINARY e.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 recipe drift';END IF;
 IF EXISTS(SELECT 1 FROM rrc150_before e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR(SELECT COUNT(*)FROM tradeskill_recipe_entries WHERE recipe_id=4507)<>7 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 old entry/count drift';END IF;
 IF(SELECT COUNT(*)FROM tradeskill_recipe_entries WHERE `recipe_id` <=> 4507 AND `item_id` <=> 12060 AND `successcount` <=> 0 AND `failcount` <=> 0 AND `componentcount` <=> 1 AND `salvagecount` <=> 1 AND `iscontainer` <=> 0)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 named component state mismatch';END IF;
 IF(SELECT COUNT(DISTINCT a.recipe_id)FROM tradeskill_recipe_entries a WHERE a.item_id=22564 AND a.componentcount>0 AND a.iscontainer=0 AND(SELECT SUM(e.componentcount)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0)=4 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=12046)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=22076)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=22095)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=22564)=1)<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 full input universe drift';END IF;
 IF(SELECT COUNT(DISTINCT a.recipe_id)FROM tradeskill_recipe_entries a WHERE a.item_id=22564 AND a.componentcount>0 AND a.iscontainer=0 AND(SELECT SUM(e.componentcount)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0)=5 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=22564)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=12046)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=12060)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=22095)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=22076)=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 full input universe drift';END IF;
 IF(SELECT COUNT(*)FROM tradeskill_recipe)<>recipes_before OR(SELECT COUNT(*)FROM tradeskill_recipe_entries)<>entries_before+1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC150 global row-count delta';END IF;
 DROP TEMPORARY TABLE rrc150_after_recipes;
 DROP TEMPORARY TABLE rrc150_before;
 DROP TEMPORARY TABLE rrc150_recipes;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT 'RRC150',changed_recipe_rows,changed_rows,recipes_before,(SELECT COUNT(*)FROM tradeskill_recipe),entries_before,(SELECT COUNT(*)FROM tradeskill_recipe_entries),@@in_transaction;
END//
DELIMITER ;
